const url = 'https://api.webscraper.io/api/v1/scraping-job/123/json';
const options = {
  method: 'GET',
  headers: {
    Accept: 'application/json, application/jsonl',
    Authorization: 'Bearer 123'
  }
};

try {
  const response = await fetch(url, options);
  const data = await response.text();
  console.log(data);
} catch (error) {
  console.error(error);
}

